    let pid = unsafe { getpid() };
    let uid = unsafe { getuid() };
    let page_size = unsafe { sysconf(libc::_SC_PAGESIZE) };
    let clk_tck = unsafe { sysconf(libc::_SC_CLK_TCK) };

