#!/bin/bash
SYS=/tmp/sysroot/usr/lib/aarch64-linux-gnu
GCC=/tmp/sysroot/usr/lib/gcc/aarch64-linux-gnu/12
pie=0
args=()
for a in "$@"; do
  case "$a" in
    -nodefaultlibs) ;;
    -pie) pie=1; args+=("$a") ;;
    -Wl,*)
      IFS=',' read -ra parts <<< "${a#-Wl,}"
      args+=("${parts[@]}") ;;
    *) args+=("$a") ;;
  esac
done
start=()
end=()
if [ "$pie" -eq 1 ]; then
  start+=("$SYS/Scrt1.o" "$SYS/crti.o" "$GCC/crtbeginS.o")
  end+=("$GCC/crtendS.o" "$SYS/crtn.o")
else
  start+=("$SYS/crt1.o" "$SYS/crti.o" "$GCC/crtbegin.o")
  end+=("$GCC/crtend.o" "$SYS/crtn.o")
fi
exec "$HOME/.rustup/toolchains/stable-aarch64-unknown-linux-gnu/lib/rustlib/aarch64-unknown-linux-gnu/bin/rust-lld" \
  -flavor gnu -L"$SYS" -L"$GCC" "${start[@]}" "${args[@]}" "${end[@]}"

